<?php

declare(strict_types=1);

namespace App\Calls\Text;

use App\Contracts\Domains\CallSender;
use App\Data\TextSections;
use App\Data\TextVersionSummary;
use App\Support\TextPart;

/**
 * The signed calls of Text, generated by php artisan journal:calls; run it again instead of editing.
 */
final readonly class TextCalls
{
    public function __construct(private CallSender $sender) {}

    public function listTextSections(
        string $target,
        string $version,
        int $afterSection = 0,
        int|null $perPage = null,
    ): TextSections {
        return $this->sender->send(ListTextSectionsCall::from([
            'target' => $target,
            'version' => $version,
            'afterSection' => $afterSection,
            'perPage' => $perPage,
        ]));
    }

    public function readText(
        string $target,
        string $version,
        string|null $section = null,
        int|null $firstLine = null,
        int|null $lastLine = null,
    ): TextPart {
        return $this->sender->send(ReadTextCall::from([
            'target' => $target,
            'version' => $version,
            'section' => $section,
            'firstLine' => $firstLine,
            'lastLine' => $lastLine,
        ]));
    }

    public function readTextVersion(
        string $target,
        string|null $version = null,
    ): TextVersionSummary {
        return $this->sender->send(ReadTextVersionCall::from([
            'target' => $target,
            'version' => $version,
        ]));
    }
}
